use std::collections::HashMap;
use std::fs;
use std::io::{self, BufRead};
use std::os::unix::io::AsRawFd;
use std::path::{Path, PathBuf};
use std::process::{Command, Child};
use std::time::Duration;
use std::thread;

use notify::{Watcher, RecursiveMode, Result as NotifyResult};
use notify::watcher;

struct Config {
    flags: Flags,
    utility: String,
    args: Vec<String>,
}

#[derive(Default)]
struct Flags {
    all_events: bool,        // -a
    clear_screen: bool,      // -c (single)
    clear_scrollback: bool,  // -cc (double)
    track_directories: bool, // -d (single)
    track_all_entries: bool, // -dd (double)
    non_interactive: bool,   // -n
    postpone: bool,          // -p
    reload: bool,            // -r
    shell: bool,             // -s
    exit_status: bool,       // -x
    shell_commands: bool,    // -xx
    exit_after: bool,        // -z
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    match parse_args(&args) {
        Ok(config) => {
            if let Err(e) = run(config) {
                eprintln!("executable: {}", e);
                std::process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("executable: {}", e);
            eprintln!("usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames");
            std::process::exit(1);
        }
    }
}

fn parse_args(args: &[String]) -> Result<Config, String> {
    if args.len() < 2 {
        return Err("No arguments provided".to_string());
    }

    let mut flags = Flags::default();
    let mut idx = 1;

    // Parse flags
    while idx < args.len() && args[idx].starts_with('-') && args[idx] != "-" {
        let flag_str = &args[idx];
        if flag_str == "-h" || flag_str == "--help" {
            print_help();
            std::process::exit(0);
        }

        // Parse flag characters
        for ch in flag_str.chars().skip(1) {
            match ch {
                'a' => flags.all_events = true,
                'c' => {
                    if flags.clear_screen {
                        flags.clear_scrollback = true;
                    }
                    flags.clear_screen = true;
                }
                'd' => {
                    if flags.track_directories {
                        flags.track_all_entries = true;
                    }
                    flags.track_directories = true;
                }
                'n' => flags.non_interactive = true,
                'p' => flags.postpone = true,
                'r' => flags.reload = true,
                's' => flags.shell = true,
                'x' => {
                    if flags.exit_status {
                        flags.shell_commands = true;
                    }
                    flags.exit_status = true;
                }
                'z' => flags.exit_after = true,
                _ => return Err(format!("Unknown flag: {}", ch)),
            }
        }
        idx += 1;
    }

    if idx >= args.len() {
        return Err("No utility specified".to_string());
    }

    let utility = args[idx].to_string();
    let args_list = args[idx + 1..].to_vec();

    Ok(Config {
        flags,
        utility,
        args: args_list,
    })
}

fn print_help() {
    println!("release: 5.7");
    println!("usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames");
    println!("summary:");
    println!("    -a  Do not consolidate events");
    println!("    -c  Clear screen before execution");
    println!("    -d  Track files added or removed from directories");
    println!("    -n  Non-interactive mode");
    println!("    -p  Wait for first event");
    println!("    -r  Run as a background process, use signal to restart");
    println!("    -s  Evaluate using a shell");
    println!("    -x  Format exit status");
    println!("    -z  Exit after the utility completes");
    println!("docs:");
    println!("    man entr");
}

fn run(config: Config) -> Result<(), String> {
    // Read file list from stdin
    let stdin = io::stdin();
    let reader = stdin.lock();
    let mut files = Vec::new();

    for line in reader.lines() {
        let line = line.map_err(|e| format!("Failed to read stdin: {}", e))?;
        let trimmed = line.trim();
        if !trimmed.is_empty() {
            // Check if file exists
            if fs::metadata(trimmed).is_ok() {
                files.push(PathBuf::from(trimmed));
            } else {
                return Err(format!("unable to stat '{}'", trimmed));
            }
        }
    }

    if files.is_empty() {
        return Err("No regular files to watch".to_string());
    }

    // Setup file watching
    let (tx, rx) = std::sync::mpsc::channel();

    let mut watcher = watcher(tx, Duration::from_millis(100))
        .map_err(|e| format!("Failed to create watcher: {}", e))?;

    for file in &files {
        watcher.watch(file, RecursiveMode::NonRecursive)
            .map_err(|e| format!("Failed to watch file: {}", e))?;
    }

    // Watch parent directories if -d flag is set
    if config.flags.track_directories {
        for file in &files {
            if let Some(parent) = file.parent() {
                let _ = watcher.watch(parent, RecursiveMode::NonRecursive);
            }
        }
    }

    // First execution if not postponed
    if !config.flags.postpone {
        execute_command(&config, &files[0])?;
        if config.flags.exit_after {
            return Ok(());
        }
    }

    // Watch loop
    loop {
        match rx.recv() {
            Ok(_event) => {
                execute_command(&config, &files[0])?;
                if config.flags.exit_after {
                    return Ok(());
                }
            }
            Err(_) => break,
        }
    }

    Ok(())
}

fn execute_command(config: &Config, first_file: &Path) -> Result<(), String> {
    if config.flags.clear_screen {
        if config.flags.clear_scrollback {
            print!("\x1B[2J\x1B[3J");
        } else {
            print!("\x1B[2J");
        }
    }

    let first_file_str = first_file.to_string_lossy().to_string();

    if config.flags.shell {
        execute_shell_command(config, &first_file_str)
    } else {
        execute_regular_command(config, &first_file_str)
    }
}

fn execute_regular_command(config: &Config, first_file: &str) -> Result<(), String> {
    let mut cmd = Command::new(&config.utility);

    for arg in &config.args {
        if arg == "/_" {
            cmd.arg(first_file);
        } else {
            cmd.arg(arg);
        }
    }

    let status = cmd.status()
        .map_err(|e| format!("Failed to execute command: {}", e))?;

    Ok(())
}

fn execute_shell_command(config: &Config, first_file: &str) -> Result<(), String> {
    if config.args.is_empty() {
        return Err("No command provided for shell execution".to_string());
    }

    let shell_cmd = config.args[0].clone();

    let mut cmd = Command::new("/bin/sh");
    cmd.arg("-c").arg(&shell_cmd);
    cmd.env("0", first_file);

    let status = cmd.status()
        .map_err(|e| format!("Failed to execute shell command: {}", e))?;

    Ok(())
}
